exercise.solution:
model LabL07Student {
  id          Int                @id @default(autoincrement())
  name        String
  enrollments LabL07Enrollment[]
  @@map("lab_l07_students")
}

model LabL07Course {
  id          Int                @id @default(autoincrement())
  title       String
  enrollments LabL07Enrollment[]
  @@map("lab_l07_courses")
}

model LabL07Enrollment {
  studentId Int           @map("student_id")
  courseId  Int           @map("course_id")
  student   LabL07Student @relation(fields: [studentId], references: [id])
  course    LabL07Course  @relation(fields: [courseId], references: [id])
  @@id([studentId, courseId])
  @@map("lab_l07_enrollments")
}

